SELECT r.id, r.conversation_id, r.queue_seq, r.status, r.created_at, r.origin, r.goal_id, r.status_reason, r.error_message, r.started_by_message_id, r.retry_of, r.agent_id_used, r.agent_config_used_id, r.model_override_provider, r.model_override, r.model_params_override, r.run_id FROM (SELECT t.* FROM  (SELECT c.* , 0 AS should_delete FROM turn c)  t) r WHERE $criteria.CompositeIn("r", $WriterKeys)